var PD_MODELS = {
  'gpt-4o':          { input: 2.50,  output: 10.00 },
  'gpt-4o-mini':     { input: 0.15,  output: 0.60  },
  'claude-sonnet':   { input: 3.00,  output: 15.00 },
  'claude-haiku':    { input: 0.80,  output: 4.00  },
  'deepseek-chat':   { input: 0.14,  output: 0.28  },
  'qwen-plus':       { input: 0.11,  output: 0.28  }
};

function estimateTokens(text){
  var s = String(text == null ? '' : text);
  if (!s) return 0;
  var cjk = 0, other = '';
  for (var i = 0; i < s.length; i++){
    var c = s.charCodeAt(i);
    if ((c >= 0x4e00 && c <= 0x9fff) || (c >= 0x3040 && c <= 0x30ff) || (c >= 0xac00 && c <= 0xd7af)) cjk++;
    else other += s.charAt(i);
  }
  return Math.ceil(cjk * 1.6 + other.length / 4);
}

function splitLines(text){
  var s = String(text == null ? '' : text);
  if (s === '') return [];
  return s.replace(/\r\n/g, '\n').split('\n');
}

function lcsMatrix(a, b){
  var m = a.length, n = b.length, i, j;
  var d = [];
  for (i = 0; i <= m; i++){ d.push(new Array(n + 1)); d[i][0] = 0; }
  for (j = 0; j <= n; j++) d[0][j] = 0;
  for (i = 1; i <= m; i++)
    for (j = 1; j <= n; j++)
      d[i][j] = a[i - 1] === b[j - 1] ? d[i - 1][j - 1] + 1 : (d[i - 1][j] > d[i][j - 1] ? d[i - 1][j] : d[i][j - 1]);
  return d;
}

function diffLines(oldText, newText){
  var a = splitLines(oldText), b = splitLines(newText);
  var d = lcsMatrix(a, b), out = [], i = a.length, j = b.length;
  while (i > 0 || j > 0){
    if (i > 0 && j > 0 && a[i - 1] === b[j - 1]){ out.push({ type: 'same', text: a[i - 1], oldNo: i, newNo: j }); i--; j--; }
    else if (j > 0 && (i === 0 || d[i][j - 1] >= d[i - 1][j])){ out.push({ type: 'add', text: b[j - 1], oldNo: null, newNo: j }); j--; }
    else { out.push({ type: 'del', text: a[i - 1], oldNo: i, newNo: null }); i--; }
  }
  out.reverse();
  return out;
}

function diffStats(rows){
  var s = { added: 0, removed: 0, same: 0 };
  for (var i = 0; i < rows.length; i++){
    if (rows[i].type === 'add') s.added++;
    else if (rows[i].type === 'del') s.removed++;
    else s.same++;
  }
  s.total = rows.length;
  s.changeRatio = rows.length ? Math.round((s.added + s.removed) / rows.length * 10000) / 10000 : 0;
  return s;
}

function wordDiff(oldLine, newLine){
  var a = String(oldLine || '').split(/(\s+)/).filter(function(x){ return x !== ''; });
  var b = String(newLine || '').split(/(\s+)/).filter(function(x){ return x !== ''; });
  var d = lcsMatrix(a, b), out = [], i = a.length, j = b.length;
  while (i > 0 || j > 0){
    if (i > 0 && j > 0 && a[i - 1] === b[j - 1]){ out.push({ type: 'same', text: a[i - 1] }); i--; j--; }
    else if (j > 0 && (i === 0 || d[i][j - 1] >= d[i - 1][j])){ out.push({ type: 'add', text: b[j - 1] }); j--; }
    else { out.push({ type: 'del', text: a[i - 1] }); i--; }
  }
  out.reverse();
  return out;
}

function tokenDelta(oldText, newText){
  var a = estimateTokens(oldText), b = estimateTokens(newText);
  return { before: a, after: b, delta: b - a,
           pct: a ? Math.round((b - a) / a * 10000) / 100 : (b ? 100 : 0) };
}

function costImpact(oldText, newText, model, callsPerDay, outputTokens){
  var m = PD_MODELS[model];
  if (!m) return { error: 'unknown model: ' + model };
  callsPerDay = callsPerDay == null ? 1000 : callsPerDay;
  outputTokens = outputTokens == null ? 300 : outputTokens;
  var t = tokenDelta(oldText, newText);
  function daily(inTok){
    return (inTok * m.input + outputTokens * m.output) / 1e6 * callsPerDay;
  }
  var before = daily(t.before), after = daily(t.after);
  return {
    error: null, model: model, tokens: t,
    dailyBefore: round4(before), dailyAfter: round4(after),
    dailyDelta: round4(after - before),
    monthlyDelta: round4((after - before) * 30),
    yearlyDelta: round4((after - before) * 365),
    monthlyDeltaCNY: round4((after - before) * 30 * 7.2)
  };
}

function round4(x){ return Math.round(x * 10000) / 10000; }

function extractVars(text){
  var s = String(text || ''), out = [], seen = {};
  var pats = [/\{\{\s*([\w.\-]+)\s*\}\}/g, /\{\s*([\w.\-]+)\s*\}/g, /\$\{\s*([\w.\-]+)\s*\}/g];
  for (var p = 0; p < pats.length; p++){
    var m;
    while ((m = pats[p].exec(s)) !== null){
      var k = m[1];
      if (!seen[k]){ seen[k] = 1; out.push(k); }
    }
  }
  return out;
}

function varDiff(oldText, newText){
  var a = extractVars(oldText), b = extractVars(newText);
  var sa = {}, sb = {}, i;
  for (i = 0; i < a.length; i++) sa[a[i]] = 1;
  for (i = 0; i < b.length; i++) sb[b[i]] = 1;
  var added = b.filter(function(x){ return !sa[x]; });
  var removed = a.filter(function(x){ return !sb[x]; });
  var kept = b.filter(function(x){ return sa[x]; });
  return { added: added, removed: removed, kept: kept,
           breaking: removed.length > 0 || added.length > 0 };
}

function lintPrompt(text){
  var s = String(text || ''), issues = [];
  var tk = estimateTokens(s);
  if (tk > 4000) issues.push({ level: 'warn', msg: '提示词超过 4000 token，考虑拆分或做检索' });
  if (!s.trim()) issues.push({ level: 'error', msg: '提示词为空' });
  if (/\bplease\b/i.test(s) && (s.match(/\bplease\b/gi) || []).length > 3)
    issues.push({ level: 'info', msg: '"please" 出现多次，礼貌用语不会提升效果，只增加 token' });
  if (/(?:sk-[A-Za-z0-9]{16,}|AKIA[0-9A-Z]{16})/.test(s))
    issues.push({ level: 'error', msg: '疑似硬编码密钥，务必移除' });
  if (s.length > 200 && !/\n/.test(s))
    issues.push({ level: 'info', msg: '长提示词无换行，建议分段以提升可读性与稳定性' });
  var open = (s.match(/\{\{/g) || []).length, close = (s.match(/\}\}/g) || []).length;
  if (open !== close) issues.push({ level: 'error', msg: '模板占位符 {{ }} 不配对（' + open + ' vs ' + close + '）' });
  if (!/(?:^|\n)\s*(?:#|##|\d+\.|-\s)/.test(s) && tk > 300)
    issues.push({ level: 'info', msg: '较长提示词缺少结构化标记（标题/列表），模型解析更易漂移' });
  return { tokens: tk, chars: s.length, issues: issues,
           errors: issues.filter(function(x){ return x.level === 'error'; }).length,
           warnings: issues.filter(function(x){ return x.level === 'warn'; }).length };
}

function compare(oldText, newText, model, calls, outTok){
  var rows = diffLines(oldText, newText);
  return {
    rows: rows, stats: diffStats(rows),
    tokens: tokenDelta(oldText, newText),
    cost: costImpact(oldText, newText, model || 'gpt-4o-mini', calls, outTok),
    vars: varDiff(oldText, newText),
    lintOld: lintPrompt(oldText), lintNew: lintPrompt(newText)
  };
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { PD_MODELS:PD_MODELS, estimateTokens:estimateTokens, splitLines:splitLines, lcsMatrix:lcsMatrix, diffLines:diffLines, diffStats:diffStats, wordDiff:wordDiff, tokenDelta:tokenDelta, costImpact:costImpact, round4:round4, extractVars:extractVars, varDiff:varDiff, lintPrompt:lintPrompt, compare:compare }; }
if (typeof window !== 'undefined') { window.PromptDiffForgePure = { PD_MODELS:PD_MODELS, estimateTokens:estimateTokens, splitLines:splitLines, lcsMatrix:lcsMatrix, diffLines:diffLines, diffStats:diffStats, wordDiff:wordDiff, tokenDelta:tokenDelta, costImpact:costImpact, round4:round4, extractVars:extractVars, varDiff:varDiff, lintPrompt:lintPrompt, compare:compare }; }
